/bin/bash -lc "python - <<'PY'
from search import run_trial
cases=[]
for y in [0.0,0.012,-0.012,0.02,-0.02]:
  for gx in [0.775,0.785,0.795,0.805]:
    for gz in [0.50,0.51,0.52,0.53]:
      params={'pre_pos':[gx,y,gz+0.04],'grasp_pos':[gx,y,gz],'lift_pos':[0.74,y,0.78],'retreat_pos':[0.71,y,0.80],
      'pre_steps':80,'down_steps':50,'settle_before_close':5,'close_steps':40,'squeeze_steps':30,'lift_steps':110,'hold_after_lift':20,'retreat_steps':30,'final_hold':20,'close_grip':0.0}
      r=run_trial(params)
      cases.append((r.score,r.passed,r.final_block_z,r.settle_contact_fraction,r.max_replay_block_z,gx,y,gz))
      print(f'score={r.score:.3f} pass={r.passed} finalz={r.final_block_z:.3f} contact={r.settle_contact_fraction:.2f} maxz={r.max_replay_block_z:.3f} gx={gx} y={y} gz={gz}', flush=True)
print('BEST', max(cases))
PY"
